     7→const isLoopbackHost = (hostname: string) => {
     8→    const normalized = String(hostname || '').trim().toLowerCase()
     9→    return normalized === 'localhost' || normalized === '127.0.0.1' || normalized === '::1'
    10→}
    11→
    12→const isPrivateIpv4Host = (hostname: string) => {
    13→    const parts = String(hostname || '').trim().split('.')
    14→    if (parts.length !== 4) return false
    15→    const nums = parts.map((p) => parseInt(p, 10))
    16→    if (nums.some((n) => !Number.isFinite(n) || n < 0 || n > 255)) return false
    17→    const [a, b] = nums
    18→    if (a === 10) return true
    19→    if (a === 192 && b === 168) return true
    20→    if (a === 172 && b >= 16 && b <= 31) return true
    21→    if (a === 100 && b >= 64 && b <= 127) return true // CGNAT
    22→    if (a === 169 && b === 254) return true // link-local
    23→    return false
    24→}
    25→
    26→const isLocalNetworkHost = (hostname: string) => {
    27→    const lower = String(hostname || '').trim().toLowerCase()
    28→    if (isLoopbackHost(lower)) return true
    29→    if (isPrivateIpv4Host(lower)) return true
    30→    if (lower.startsWith('fd') || lower.startsWith('fc') || lower.startsWith('fe80:')) return true
    31→    if (lower.endsWith('.local') || lower.endsWith('.lan')) return true
    32→    return false
    33→}
