    44→const getDefaultControlServerBaseUrl = (): string => {
    45→    if (typeof window === 'undefined') return ''
    46→
    47→    const isDev = typeof import.meta !== 'undefined' && Boolean(import.meta.env?.DEV)
    48→    const { hostname, port, protocol } = window.location
    49→    const isLoopback = isLoopbackHost(hostname)
    50→    const portNum = parseInt(port || '', 10)
    51→
    52→    // Dev default: point the SPA to the local API unless explicitly configured.
    53→    if (isDev && isLoopback) return 'http://127.0.0.1:3001'
    54→
    55→    // If the UI is accessed via a LAN IP / .local hostname, default the API to the same host on port 3001.
    56→    // This supports opening the wizard from another device (phone/tablet) while the control-server runs on the host.
    57→    if (!isLoopback) {
    58→        if (isLocalNetworkHost(hostname)) {
    59→            if (Number.isFinite(portNum) && portNum === 3001) return ''
    60→            return `${protocol}//${hostname}:3001`
    61→        }
    62→        return ''
    63→    }
    64→
    65→    // For any loopback-hosted UI (including IDE browser preview proxy ports),
    66→    // default API calls to the local control-server.
    67→    // This avoids sending /api requests to the UI origin, which commonly returns
    68→    // SPA HTML with a 200 and can break JSON parsing in startup hooks.
    69→    if (!Number.isFinite(portNum)) return 'http://127.0.0.1:3001'
    70→    if (portNum === 3001) return ''
    71→    return 'http://127.0.0.1:3001'
    72→}
