    87→export const getControlServerBaseUrl = (): string => {
    88→    if (envUrl) {
    89→        if (typeof window !== 'undefined') {
    90→            try {
    91→                const parsed = new URL(envUrl)
    92→                const envHost = parsed.hostname
    93→                const envPort = parsed.port || '3001'
    94→                const pageHost = window.location.hostname
    95→                if (isLoopbackHost(envHost) && !isLoopbackHost(pageHost) && isLocalNetworkHost(pageHost)) {
    96→                    return `${parsed.protocol}//${pageHost}:${envPort}`
    97→                }
    98→            } catch {
    99→                // ignore parse failures and use envUrl as-is
   100→            }
   101→        }
   102→        return envUrl
   103→    }
   104→    if (typeof window === 'undefined') return ''
   105→    try {
   106→        const stored = window.localStorage.getItem(CONTROL_SERVER_URL_STORAGE_KEY)
   107→        if (stored) return stored.trim().replace(/\/$/, '')
   108→    } catch {
   109→        // ignore storage failures
   110→    }
   111→    return getDefaultControlServerBaseUrl()
   112→}
