   114→export const setControlServerBaseUrl = (nextUrl: string) => {
   115→    if (typeof window === 'undefined') return
   116→    const trimmed = String(nextUrl || '').trim().replace(/\/$/, '')
   117→    try {
   118→        if (!trimmed) window.localStorage.removeItem(CONTROL_SERVER_URL_STORAGE_KEY)
   119→        else window.localStorage.setItem(CONTROL_SERVER_URL_STORAGE_KEY, trimmed)
   120→    } catch {
   121→        // ignore storage failures
   122→    }
   123→}
