   125→export const getControlServerToken = (): string => {
   126→    if (envToken) return envToken
   127→    if (typeof window === 'undefined') return ''
   128→    try {
   129→        return (window.localStorage.getItem(CONTROL_SERVER_TOKEN_STORAGE_KEY) || '').trim()
   130→    } catch {
   131→        return ''
   132→    }
   133→}
   134→
   135→export const setControlServerToken = (token: string) => {
   136→    if (typeof window === 'undefined') return
   137→    const trimmed = String(token || '').trim()
   138→    try {
   139→        if (!trimmed) window.localStorage.removeItem(CONTROL_SERVER_TOKEN_STORAGE_KEY)
   140→        else window.localStorage.setItem(CONTROL_SERVER_TOKEN_STORAGE_KEY, trimmed)
   141→    } catch {
   142→        // ignore storage failures
   143→    }
   144→}
   145→
   146→export const controlServerAuthHeaders = (): Record<string, string> => {
   147→    const token = getControlServerToken()
   148→    if (!token) return {}
   149→    return { Authorization: `Bearer ${token}` }
   150→}
   151→
   152→export const buildControlServerUrl = (path: string) => {
   153→    const normalized = path.startsWith('/') ? path : `/${path}`
   154→    const configuredOrigin = getControlServerBaseUrl()
   155→
   156→    if (configuredOrigin) {
   157→        const sameOrigin = configuredOrigin === getWindowOrigin()
   158→        return sameOrigin ? normalized : `${configuredOrigin}${normalized}`
   159→    }
   160→
   161→    const fallbackOrigin = getDefaultControlServerBaseUrl() || getWindowOrigin()
   162→    if (!fallbackOrigin) return normalized
   163→
   164→    const sameOrigin = fallbackOrigin === getWindowOrigin()
   165→    return sameOrigin ? normalized : `${fallbackOrigin}${normalized}`
   166→}
